const normalizeHtmlMasterPages = (masters: HtmlMasterPage[]): HtmlMasterPage[] =>
  masters.map(master => !master.blocks
    ? master
    : {
        ...master,
        blocks: master.blocks.map(block => block.type === 'cards'
          ? { ...block, type: 'navigation-cards', label: block.label || 'Navigation Cards' }
          : block),
      })

type ListItem = { id: string; text: string; level: number; type: 'bullet' | 'ordered'; startFresh?: boolean }
type DocBlock = {
  id: string
  type: DocBlockType
  content: string
  calloutVariant?: CalloutVariant
  tableData?: { rows: string[][]; hasHeader: boolean }
  procedureSteps?: string[]
  mediaType?: string
  caption?: string
  conditions?: string[]
  listItems?: ListItem[]
}

function collectAnalyzableContent(
  documentBlocks: DocBlock[],
  topicContent: Record<string, DocBlock[]>,
): AnalyzableContentItem[] {
  const items: AnalyzableContentItem[] = []
  const seen = new Set<string>()
  const addBlock = (block: DocBlock, baseLocation: string, topicId?: string) => {
    const add = (
      suffix: string,
      text: string,
      contextType: AnalyzableContentItem['contextType'],
      location: string,
    ) => {
      const cleaned = text.trim()
      if (!cleaned) return
      const key = `${block.id}|${suffix}|${cleaned}`
      if (seen.has(key)) return
      seen.add(key)
      items.push({
        id: `${block.id}-${suffix}`,
        text: cleaned,
        contextType,
        location,
        blockId: block.id,
        topicId,
      })
    }

    if (!['h1', 'h2', 'h3', 'h4', 'code', 'divider', 'media', 'variable', 'bookmark'].includes(block.type)) {
      add('content', block.content, topicId ? 'topic-block' : 'document-block', baseLocation)
    }
    block.procedureSteps?.forEach((step, index) =>
      add(`step-${index + 1}`, step, 'procedure-step', `${baseLocation} · procedure step ${index + 1}`))
    block.listItems?.forEach((item, index) =>
      add(`list-${index + 1}`, item.text, 'list-item', `${baseLocation} · list item ${index + 1}`))
    block.tableData?.rows.forEach((row, rowIndex) => row.forEach((cell, columnIndex) =>
      add(`cell-${rowIndex + 1}-${columnIndex + 1}`, cell, 'table-cell', `${baseLocation} · table row ${rowIndex + 1}, column ${columnIndex + 1}`)))
  }

  for (const [topicId, blocks] of Object.entries(topicContent).sort(([left], [right]) => left.localeCompare(right))) {
    blocks.forEach(block => addBlock(block, `Topic ${topicId} · block ${block.id}`, topicId))
  }
  documentBlocks.forEach(block => addBlock(block, `Document block ${block.id}`))
  return items
}

// ── List helpers ──────────────────────────────────────────────────────────────
function getItemLabel(items: ListItem[], index: number): string {
  const item = items[index]
  if (item.type === 'bullet') return ['•', '○', '–'][Math.min(item.level - 1, 2)]
  // Count ordered predecessors at this level, resetting on any startFresh marker
  let count = 0
  for (let i = 0; i <= index; i++) {
    const it = items[i]
    if (it.level !== item.level || it.type !== 'ordered') continue
    if (it.startFresh) count = 1
    else count++
  }
  if (item.level === 1) return `${count}.`
  if (item.level === 2) return `${String.fromCharCode(96 + count)}.`
  const romans = ['i','ii','iii','iv','v','vi','vii','viii','ix','x']
  return `${romans[Math.min(count - 1, romans.length - 1)] ?? count}.`
}

function splitAtCaret(el: HTMLElement): { before: string; after: string } {
  const sel = window.getSelection()
  if (!sel || sel.rangeCount === 0) return { before: el.innerText.replace(/\n$/, ''), after: '' }
  const range = sel.getRangeAt(0)
  if (!range.collapsed) range.collapse(true)
  const pre = document.createRange()
  pre.selectNodeContents(el)
  pre.setEnd(range.startContainer, range.startOffset)
  const before = pre.toString()
  const full = el.innerText.replace(/\n$/, '')
  return { before, after: full.slice(before.length) }
}

